def seed_curriculum(apps, schema_editor):
    Topic = apps.get_model('learning', 'LearningTopic')
    for order, row in enumerate(LESSONS, 1):
        title, category, error_name, technology, difficulty, error, buggy, corrected, root, fix, explanation, prevention, challenge, terms, hints, question, options, answer_index, answer_explanation = row
        Topic.objects.get_or_create(title=title, defaults={
            'category':category, 'error_name':error_name, 'technology':technology,
            'difficulty':difficulty, 'order':order, 'description':root,
            'explanation':explanation, 'buggy_code':buggy, 'expected_error':error,
            'corrected_code':corrected, 'correction_explanation':fix,
            'practice_question':challenge, 'practice_answer':root,
            'keywords':terms.split(), 'lesson_data':{
                'root_cause':root,'reproduce':buggy,'troubleshooting':[fix],
                'prevention':prevention,'challenge':challenge,'accepted_terms':terms.split(),
                'hints':hints,'quiz':[{'question':question,'options':options,'correct_index':answer_index,'explanation':answer_explanation}],
                'line_explanations':[{'line':1,'text':error}],
            }})


class Migration(migrations.Migration):
    dependencies = [('learning','0004_learningtopic_difficulty_learningtopic_error_name_and_more')]
    operations = [migrations.RunPython(seed_curriculum, migrations.RunPython.noop)]
